def broadcast_object(obj: Any) -> Any:
    """
    Broadcasts the object across all devices.

    Args:
        obj: The object to broadcast.

    Returns:
        The broadcasted object.
    """
    if isinstance(obj, torch.Tensor):
        obj = obj.to(torch.device("cuda"))
    elif isinstance(obj, dict):
        for k, v in obj.items():
            obj[k] = broadcast_object(v)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            obj[i] = broadcast_object(v)
    return obj


def _unix_pattern_to_parameter_names(
    patterns: List[str], parameter_names: List[str]
) -> List[str]:
    """
    Returns a list of parameter names that match the given patterns.

    Args:
        patterns: A list of patterns to match.
        parameter_names: A list of parameter names to match against.

    Returns:
        A list of parameter names that match the given patterns.
    """
    include_keys = set()
    for pattern in patterns:
        include_keys.update(
            [
                key
                for key in parameter_names
                if fnmatch.fnmatch(key, pattern)
                or fnmatch.fnmatch(key, pattern.replace("*", ""))
            ]
        )
    return list(include_keys)

