def wrap_unet(self, unet_number):
    if hasattr(self, 'one_unet_wrapped'):
        return

    unet = self.imagen.get_unet(unet_number)
    unet_index = unet_number - 1

    optimizer = getattr(self, f'optim{unet_index}')
