@property
def all_checkpoints_sorted(self):
    glob_pattern = os.path.join(self.checkpoint_path, '*.pt')
    checkpoints = self.fs.glob(glob_pattern)
    sorted_checkpoints = sorted(checkpoints, key = lambda x: int(str(x).split('.')[-2]), reverse = True)
