    unet_number = self.validate_unet_number(unet_number)
    index = unet_number - 1

    if isinstance(self.unets, nn.ModuleList):
        unets_list = [unet for unet in self.ema_unets]
        delattr(self, 'ema_unets')
        self.ema_unets = unets_list

